  const sparks = (x, y, k, v, up) => H.burst(x, y, 'spark', k, { v: v || 6, up: up || 2, g: 6, life: 0.35, size: 2.2, color: [YEL, BW, WHITE], extra: { drag: 3 } });
  /* an arc between two world points at heights z1, z2, living `life` seconds and regrowing as it fades */
  function zapFx(x1, y1, z1, x2, y2, z2, w, col, life) { H.add({ life: life || 0.2, draw(c, f, X, Y, T) { const a = Math.min(1, f.life / 0.12); arc(c, H.sx(x1), H.sy(y1) - z1 * T, H.sx(x2), H.sy(y2) - z2 * T, { w, col, a, seed: sd(f), branch: 3 }); } }); }
  /* a bolt down onto (x, y) from h tiles up, with a hot patch on the floor */
